from decimal import Decimal

def invoice_totals(rows):
    totals = {}
    for row in rows:
        sku = row["sku"]
        line_total = Decimal(row["price"]) * row["quantity"]
        totals[sku] = totals.get(sku, Decimal(0)) + line_total
    return totals

